//! Media pipeline against real HLS/DASH streams generated by FFmpeg and served locally.
//! Requires yt-dlp, ffmpeg and ffprobe on PATH; each test is skipped (passes with a note) otherwise.
//! `GALE_NET_TESTS=1` additionally runs extraction against a public YouTube video.

use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::sync::{Arc, OnceLock};
use std::time::Duration;

use axum::body::Body;
use axum::extract::{Path as UrlPath, State};
use axum::http::{header, StatusCode};
use axum::response::Response;
use axum::routing::get;
use axum::Router;
use gale_core::db::{Db, Download, DownloadStatus};
use gale_core::engine::{EngineConfig, Tick};
use gale_core::manager::{AddOptions, EventSink, Manager, MediaRequest};
use gale_core::media::{self, MediaChoice, MediaJob, MediaNet, MediaOutcome, MediaTools};
use gale_core::Error;
use tokio_util::sync::CancellationToken;

fn tools() -> Option<MediaTools> {
    MediaTools::locate(None, None).ok()
}

macro_rules! need_tools {
    () => {
        match tools() {
            Some(t) => t,
            None => {
                eprintln!("skipped: yt-dlp/ffmpeg/ffprobe not on PATH");
                return;
            }
        }
    };
}

/// Fixtures are generated once per test run.
fn fixtures() -> &'static PathBuf {
    static DIR: OnceLock<PathBuf> = OnceLock::new();
    DIR.get_or_init(|| {
        let dir = std::env::temp_dir().join(format!("gale-media-fixtures-{}", std::process::id()));
        for sub in ["hls", "dash", "long"] {
            std::fs::create_dir_all(dir.join(sub)).unwrap();
        }
        let ff = |args: &[&str]| {
            let ok = std::process::Command::new("ffmpeg").args(["-hide_banner", "-loglevel", "error", "-y"]).args(args).current_dir(&dir).status().unwrap();
            assert!(ok.success(), "ffmpeg failed: {args:?}");
        };
        // HLS: three muxed variants (360p, 720p, 1080p) behind a master playlist.
        ff(&[
            "-f", "lavfi", "-i", "testsrc2=size=1920x1080:rate=24:duration=4", "-f", "lavfi", "-i", "sine=frequency=440:duration=4",
            "-filter_complex", "[0:v]split=3[a][b][c];[a]scale=640:360[v0];[b]scale=1280:720[v1];[c]null[v2]",
            "-map", "[v0]", "-map", "1:a", "-map", "[v1]", "-map", "1:a", "-map", "[v2]", "-map", "1:a",
            "-c:v", "libx264", "-preset", "ultrafast", "-b:v", "300k", "-g", "24", "-c:a", "aac", "-b:a", "64k",
            "-f", "hls", "-hls_time", "1", "-hls_playlist_type", "vod", "-master_pl_name", "master.m3u8",
            "-var_stream_map", "v:0,a:0,name:360p v:1,a:1,name:720p v:2,a:2,name:1080p",
            "-hls_segment_filename", "hls/%v_%03d.ts", "hls/%v.m3u8",
        ]);
        // DASH: separate video and audio tracks that must be merged.
        let dash = |out: &str, secs: u32| {
            let (v, a) = (format!("testsrc2=size=1280x720:rate=24:duration={secs}"), format!("sine=frequency=660:duration={secs}"));
            ff(&[
                "-f", "lavfi", "-i", &v, "-f", "lavfi", "-i", &a, "-map", "0:v", "-map", "1:a",
                "-c:v", "libx264", "-preset", "ultrafast", "-b:v", "400k", "-g", "24", "-c:a", "aac", "-b:a", "64k",
                "-f", "dash", "-seg_duration", "1", "-adaptation_sets", "id=0,streams=v id=1,streams=a", out,
            ]);
        };
        dash("dash/manifest.mpd", 6);
        dash("long/manifest.mpd", 24);
        dir
    })
}

/// Static file server; anything under /slow/ is delayed per request to make long transfers.
async fn serve(State(root): State<Arc<PathBuf>>, UrlPath(path): UrlPath<String>) -> Response {
    let (slow, rel) = match path.strip_prefix("slow/") {
        Some(r) => (true, r.to_string()),
        None => (false, path),
    };
    if slow {
        tokio::time::sleep(Duration::from_millis(700)).await;
    }
    let file = root.join(&rel);
    if rel.contains("..") || !file.is_file() {
        return Response::builder().status(StatusCode::NOT_FOUND).body(Body::empty()).unwrap();
    }
    let ct = match file.extension().and_then(|e| e.to_str()) {
        Some("m3u8") => "application/vnd.apple.mpegurl",
        Some("mpd") => "application/dash+xml",
        Some("ts") => "video/mp2t",
        _ => "video/mp4",
    };
    Response::builder().header(header::CONTENT_TYPE, ct).body(Body::from(std::fs::read(file).unwrap())).unwrap()
}

async fn server() -> SocketAddr {
    let app = Router::new().route("/{*path}", get(serve)).with_state(Arc::new(fixtures().clone()));
    let l = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = l.local_addr().unwrap();
    tokio::spawn(async move { axum::serve(l, app).await.unwrap() });
    addr
}

fn url(addr: SocketAddr, p: &str) -> url::Url {
    format!("http://{addr}/{p}").parse().unwrap()
}

async fn run(t: &MediaTools, u: url::Url, choice: MediaChoice, dir: &Path) -> gale_core::Result<PathBuf> {
    let job = MediaJob {
        url: u,
        choice,
        save_dir: dir.to_path_buf(),
        work_dir: dir.join(".work"),
        concurrent_fragments: 4,
        expected_bytes: None,
        net: MediaNet { timeout_secs: 20, ..Default::default() },
    };
    let stages = Arc::new(std::sync::Mutex::new(Vec::<&'static str>::new()));
    let s2 = stages.clone();
    let cb = move |p: media::MediaProgress| {
        let mut s = s2.lock().unwrap();
        if s.last() != Some(&p.stage) {
            s.push(p.stage);
        }
    };
    match media::download(t, &job, &CancellationToken::new(), &cb).await? {
        MediaOutcome::Completed { path, bytes } => {
            assert!(bytes > 0);
            let s = stages.lock().unwrap();
            assert_eq!(s.first(), Some(&"extracting"));
            assert_eq!(s.last(), Some(&"verifying"), "stages: {s:?}");
            assert!(!dir.join(".work").exists(), "work folder cleaned up");
            Ok(path)
        }
        o => panic!("unexpected {o:?}"),
    }
}

async fn streams(t: &MediaTools, p: &Path) -> Vec<(String, String)> {
    media::probe_streams(t, p).await.unwrap()
}

async fn height(p: &Path) -> u32 {
    let out = tokio::process::Command::new("ffprobe")
        .args(["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=height", "-of", "csv=p=0"])
        .arg(p)
        .output()
        .await
        .unwrap();
    String::from_utf8_lossy(&out.stdout).trim().parse().unwrap()
}

#[tokio::test]
async fn hls_360_720_1080() {
    let t = need_tools!();
    let addr = server().await;
    let info = media::extract(&t, &url(addr, "hls/master.m3u8"), &MediaNet::default()).await.unwrap();
    let labels: Vec<_> = info.options.iter().map(|o| o.label.as_str()).collect();
    assert_eq!(&labels[..3], ["1080p", "720p", "360p"], "{labels:?}");
    assert!(info.options[..3].iter().all(|o| o.kind == "hls"));
    for h in [360, 720, 1080] {
        let dir = tempfile::tempdir().unwrap();
        let p = run(&t, url(addr, "hls/master.m3u8"), MediaChoice::Video { max_height: Some(h) }, dir.path()).await.unwrap();
        assert_eq!(height(&p).await, h);
        let s = streams(&t, &p).await;
        assert!(s.iter().any(|x| x.0 == "audio"), "{h}p has audio: {s:?}");
        assert_eq!(p.extension().unwrap(), "mp4");
    }
}

#[tokio::test]
async fn dash_separate_audio_and_video_are_merged_to_mp4() {
    let t = need_tools!();
    let addr = server().await;
    let info = media::extract(&t, &url(addr, "dash/manifest.mpd"), &MediaNet::default()).await.unwrap();
    let v = &info.options[0];
    assert_eq!((v.label.as_str(), v.kind.as_str()), ("720p", "dash"));
    assert!(v.detail.contains("merged"), "{}", v.detail);
    let dir = tempfile::tempdir().unwrap();
    let p = run(&t, url(addr, "dash/manifest.mpd"), v.choice, dir.path()).await.unwrap();
    let s = streams(&t, &p).await;
    assert!(s.contains(&("video".into(), "h264".into())) && s.contains(&("audio".into(), "aac".into())), "stream copy, no re-encode: {s:?}");
    assert_eq!(p.extension().unwrap(), "mp4");
}

#[tokio::test]
async fn audio_only_mp3_and_original() {
    let t = need_tools!();
    let addr = server().await;
    let dir = tempfile::tempdir().unwrap();
    let mp3 = run(&t, url(addr, "dash/manifest.mpd"), MediaChoice::Audio { mp3: true }, dir.path()).await.unwrap();
    assert_eq!(streams(&t, &mp3).await, [("audio".to_string(), "mp3".to_string())]);
    let dir = tempfile::tempdir().unwrap();
    let orig = run(&t, url(addr, "dash/manifest.mpd"), MediaChoice::Audio { mp3: false }, dir.path()).await.unwrap();
    assert_eq!(streams(&t, &orig).await, [("audio".to_string(), "aac".to_string())]);
}

#[tokio::test]
async fn failed_extraction_reports_the_reason() {
    let t = need_tools!();
    let addr = server().await;
    let e = media::extract(&t, &url(addr, "missing/nothing.m3u8"), &MediaNet::default()).await.unwrap_err();
    assert_eq!(e.code(), "media");
    assert!(e.to_string().contains("404"), "{e}");
}

#[tokio::test]
async fn ffmpeg_failure_is_an_error_not_a_bad_file() {
    let mut t = need_tools!();
    let addr = server().await;
    let fake = tempfile::tempdir().unwrap();
    let broken = fake.path().join("ffmpeg");
    std::fs::write(&broken, "#!/bin/sh\necho 'ffmpeg: simulated failure' >&2\nexit 1\n").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&broken, std::fs::Permissions::from_mode(0o755)).unwrap();
    }
    t.ffmpeg = broken;
    let dir = tempfile::tempdir().unwrap();
    let r = run(&t, url(addr, "dash/manifest.mpd"), MediaChoice::Video { max_height: Some(720) }, dir.path()).await;
    assert!(matches!(r, Err(Error::Media(_))), "{r:?}");
    let leftovers: Vec<_> = std::fs::read_dir(dir.path()).unwrap().flatten().filter(|e| e.path().is_file()).map(|e| e.path()).collect();
    assert!(leftovers.is_empty(), "nothing half-made in the user's folder after a failed merge: {leftovers:?}");
}

// ---------------------------------------------------------------------------------------------
// Through the manager: queue/history integration, pause/resume, cancel

struct Events(Arc<std::sync::Mutex<Vec<&'static str>>>);
impl EventSink for Events {
    fn progress(&self, _: i64, t: &Tick) {
        if let Some(s) = t.stage {
            let mut v = self.0.lock().unwrap();
            if v.last() != Some(&s) {
                v.push(s);
            }
        }
    }
    fn changed(&self, _: &Download) {}
}

async fn manager(dir: &Path, t: MediaTools) -> (Arc<Manager>, Arc<std::sync::Mutex<Vec<&'static str>>>) {
    let stages = Arc::new(std::sync::Mutex::new(vec![]));
    let m = Manager::new(Db::open(&dir.join("gale.db")).await.unwrap(), EngineConfig { connections: 4, ..Default::default() }, 3, Arc::new(Events(stages.clone()))).unwrap();
    m.set_media_tools(Some(t));
    (m, stages)
}

async fn wait(m: &Manager, id: i64, f: impl Fn(&Download) -> bool) -> Download {
    for _ in 0..1200 {
        let d = m.db().get_download(id).await.unwrap();
        if f(&d) {
            return d;
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    panic!("timeout: {:?}", m.db().get_download(id).await.unwrap());
}

fn media_opts(u: url::Url, dir: &Path, choice: MediaChoice) -> AddOptions {
    AddOptions {
        url: u.to_string(),
        save_dir: dir.to_string_lossy().into(),
        start: true,
        media: Some(MediaRequest { choice, kind: "dash".into(), title: Some("Test clip".into()), expected_bytes: None }),
        ..Default::default()
    }
}

fn ytdlp_running_in(dir: &Path) -> bool {
    std::process::Command::new("pgrep").args(["-f", &dir.to_string_lossy()]).status().map(|s| s.success()).unwrap_or(false)
}

#[tokio::test]
async fn pause_and_resume_media_then_history() {
    let t = need_tools!();
    let addr = server().await;
    let dir = tempfile::tempdir().unwrap();
    let (m, stages) = manager(dir.path(), t.clone()).await;
    let id = m.add(media_opts(url(addr, "slow/long/manifest.mpd"), dir.path(), MediaChoice::Video { max_height: Some(720) })).await.unwrap();
    let d = wait(&m, id, |d| d.downloaded_bytes > 0).await;
    assert_eq!(d.kind, "dash");
    m.stop_and_wait(id).await.unwrap();
    let paused = m.db().get_download(id).await.unwrap();
    assert_eq!(paused.status, DownloadStatus::Paused);
    assert!(Path::new(paused.temp_path.as_deref().unwrap()).exists(), "fragments kept for resume");
    assert!(!ytdlp_running_in(&dir.path().join(format!(".gale-media-{id}"))), "child processes stopped");

    m.start(id).await.unwrap();
    let done = wait(&m, id, |d| matches!(d.status, DownloadStatus::Completed | DownloadStatus::Failed)).await;
    assert_eq!(done.status, DownloadStatus::Completed, "{:?}", done.error_message);
    let p = PathBuf::from(done.final_path.unwrap());
    let s = streams(&t, &p).await;
    assert!(s.iter().any(|x| x.0 == "video") && s.iter().any(|x| x.0 == "audio"));
    assert!(done.file_name.starts_with("Test") || done.file_name.contains("manifest"), "{}", done.file_name);
    assert_eq!(m.db().list_history(5).await.unwrap()[0].outcome, "completed");
    let st = stages.lock().unwrap().clone();
    assert!(st.contains(&"downloading") && st.contains(&"merging") && st.ends_with(&["verifying"]), "{st:?}");
}

#[tokio::test]
async fn cancel_stops_processes_and_removes_temp_files() {
    let t = need_tools!();
    let addr = server().await;
    let dir = tempfile::tempdir().unwrap();
    let (m, _) = manager(dir.path(), t).await;
    let id = m.add(media_opts(url(addr, "slow/long/manifest.mpd"), dir.path(), MediaChoice::Video { max_height: Some(720) })).await.unwrap();
    wait(&m, id, |d| d.downloaded_bytes > 0).await;
    let work = dir.path().join(format!(".gale-media-{id}"));
    assert!(work.exists());
    m.cancel(id).await.unwrap();
    assert_eq!(m.db().get_download(id).await.unwrap().status, DownloadStatus::Cancelled);
    assert!(!work.exists(), "work folder removed");
    tokio::time::sleep(Duration::from_millis(300)).await;
    assert!(!ytdlp_running_in(&work), "no yt-dlp/ffmpeg left behind");
}

#[tokio::test]
async fn missing_tools_fail_cleanly() {
    let dir = tempfile::tempdir().unwrap();
    let m = Manager::new(Db::open(&dir.path().join("g.db")).await.unwrap(), EngineConfig::default(), 1, Arc::new(Events(Default::default()))).unwrap();
    assert_eq!(m.extract_media("https://example.com/v").await.unwrap_err().code(), "tool_missing");
}

#[tokio::test]
async fn real_youtube_extraction() {
    if std::env::var("GALE_NET_TESTS").as_deref() != Ok("1") {
        eprintln!("skipped: set GALE_NET_TESTS=1 to query YouTube");
        return;
    }
    let t = need_tools!();
    // "Me at the zoo", the first YouTube upload: public and short.
    let info = media::extract(&t, &"https://www.youtube.com/watch?v=jNQXAC9IVRw".parse().unwrap(), &MediaNet { timeout_secs: 30, ..Default::default() }).await.unwrap();
    assert_eq!(info.extractor, "youtube");
    let labels: Vec<_> = info.options.iter().map(|o| o.label.clone()).collect();
    assert!(labels.contains(&"240p".to_string()) && labels.contains(&"Audio only (MP3)".to_string()), "{labels:?}");
    eprintln!("YouTube options: {labels:?}");
}

